<template>
  <section class="scanner-page"><div class="scanner-inner"><p class="eyebrow">HARI SANTRI 2026 / TENANT</p><h1>Scanner voucher</h1><p class="intro">Pilih lapak dari daftar akun exhibitor yang sedang login. Scan QR voucher peserta, masukkan nominal belanja, lalu minta peserta mengonfirmasi dengan password akunnya. Transaksi yang berhasil tidak dapat dibatalkan.</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><div class="grid"><div class="panel"><label>Pilih lapak<select v-model="selectedExhibitorId" @change="loadWallet"><option value="">Pilih lapak</option><option v-for="exhibitor in exhibitors" :key="exhibitor.exhibitor_id" :value="exhibitor.exhibitor_id">{{ exhibitor.business_name }} · {{ exhibitor.status }}</option></select></label><button type="button" class="button secondary full" :disabled="!selectedExhibitorId" @click="loadWallet">Muat saldo exhibitor</button><div id="voucher-reader" class="reader" /><button type="button" class="button secondary full" @click="startCamera">Aktifkan kamera</button><label>Token QR voucher<input v-model.trim="form.qr_token" autocomplete="off" placeholder="Fallback input bila kamera tidak tersedia"></label><label>Nominal belanja (IDR)<input v-model.number="form.amount" type="number" min="1"></label><label>Password peserta<input v-model="form.participant_password" type="password" autocomplete="off"></label><button type="button" class="button primary full" :disabled="busy || retryAfterSeconds > 0 || !form.qr_token || !form.amount" @click="charge">{{ retryAfterSeconds > 0 ? `Coba lagi dalam ${retryAfterSeconds} detik` : 'Konfirmasi transaksi' }}</button></div><div class="panel balance"><span class="eyebrow">SALDO TENANT</span><strong>{{ money(balance) }}</strong><p>{{ filteredTransfers.length }} transaksi · total {{ money(totalSpent) }}</p><div class="date-filter"><label>Dari<input v-model="dateFrom" type="date"></label><label>Sampai<input v-model="dateTo" type="date"></label><button type="button" class="button secondary full" @click="loadWallet">Terapkan filter</button></div><h2>Transaksi terbaru</h2><table><tbody><tr v-for="row in filteredTransfers.slice(0,10)" :key="row.transfer_id"><td>{{ formatDate(row.created_at) }}</td><td>{{ money(row.amount) }}</td></tr></tbody></table></div><div class="panel settlement"><h2>Settlement saldo</h2><p>Ajukan seluruh saldo yang tersedia untuk dibayar panitia, lalu konfirmasi setelah transfer diterima.</p><label>Referensi transfer<input v-model.trim="settlementForm.reference" placeholder="Opsional"></label><label>Settlement ID untuk konfirmasi<input v-model.trim="settlementId" placeholder="Diisi setelah pengajuan"></label><button type="button" class="button primary full" :disabled="busy || !selectedExhibitorId || balance <= 0" @click="requestSettlement">Ajukan seluruh saldo</button><button type="button" class="button secondary full" :disabled="busy || !settlementId" @click="confirmSettlement">Konfirmasi pembayaran diterima</button></div></div></div></section>
</template>

<script setup lang="ts">
import { BrowserMultiFormatReader } from '@zxing/browser';
import type { MyExhibitor, WalletTransfer } from '~/composables/useVoucherWallet';
import { useVoucherWallet } from '~/composables/useVoucherWallet';

definePageMeta({ middleware: 'auth' });
const walletApi = useVoucherWallet();
const exhibitors = ref<MyExhibitor[]>([]); const selectedExhibitorId = ref('');
const balance = ref(0); const transfers = ref<WalletTransfer[]>([]); const dateFrom = ref(''); const dateTo = ref(''); const busy = ref(false); const error = ref(''); const success = ref('');
const retryAfterSeconds = ref(0); let retryTimer: ReturnType<typeof setInterval> | undefined;
const filteredTransfers = computed(() => transfers.value); const totalSpent = computed(() => filteredTransfers.value.reduce((total, row) => total + row.amount, 0));
const form = reactive({ qr_token: '', amount: 0, participant_password: '' });
const settlementForm = reactive({ reference: '' }); const settlementId = ref('');
const requestId = ref(`scan-${Date.now()}`); let reader: BrowserMultiFormatReader | null = null;
const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0);
const formatDate = (value: string) => new Intl.DateTimeFormat('id-ID', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value));
const loadWallet = async () => { if (!selectedExhibitorId.value) return; error.value = ''; try { const [wallet, history] = await Promise.all([walletApi.selectedExhibitorWallet(selectedExhibitorId.value), walletApi.selectedExhibitorTransfers(selectedExhibitorId.value, { date_from: dateFrom.value || undefined, date_to: dateTo.value || undefined })]); balance.value = wallet.data.balance; transfers.value = history.data; } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Saldo tenant belum dapat dimuat.'; } };
const startCamera = async () => { error.value = ''; try { reader ||= new BrowserMultiFormatReader(); await reader.decodeFromVideoDevice(undefined, 'voucher-reader', (result) => { if (result) form.qr_token = result.getText(); }); } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Kamera tidak dapat digunakan.'; } };
const charge = async () => { busy.value = true; error.value = ''; success.value = ''; try { const result = await walletApi.chargeSelectedExhibitor(selectedExhibitorId.value, { ...form, request_id: requestId.value, amount: Number(form.amount) }); balance.value = result.data.exhibitor_balance; success.value = `Transaksi ${money(result.data.amount)} berhasil. Saldo tenant ${money(result.data.exhibitor_balance)}.`; form.qr_token = ''; form.amount = 0; form.participant_password = ''; requestId.value = `scan-${Date.now()}`; await loadWallet(); } catch (cause) { const failure = cause as { status?: number; statusCode?: number; response?: { status?: number; headers?: Headers }; data?: { detail?: string; message?: string }; message?: string }; const statusCode = failure.response?.status ?? failure.statusCode ?? failure.status; error.value = failure.data?.detail || failure.data?.message || (cause instanceof Error ? cause.message : 'Transaksi gagal.'); if (statusCode === 429) { retryAfterSeconds.value = Math.max(1, Number(failure.response?.headers?.get('Retry-After')) || 60); if (retryTimer) clearInterval(retryTimer); retryTimer = setInterval(() => { retryAfterSeconds.value = Math.max(0, retryAfterSeconds.value - 1); if (retryAfterSeconds.value === 0 && retryTimer) { clearInterval(retryTimer); retryTimer = undefined; } }, 1000); } } finally { busy.value = false; } };
const requestSettlement = async () => { busy.value = true; error.value = ''; success.value = ''; try { const result = await walletApi.requestMySettlement(selectedExhibitorId.value, { payment_reference: settlementForm.reference }); settlementId.value = result.data.settlement_id; success.value = `Settlement ${money(result.data.amount)} berhasil diajukan.`; settlementForm.reference = ''; } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Settlement gagal diajukan.'; } finally { busy.value = false; } };
const confirmSettlement = async () => { busy.value = true; error.value = ''; success.value = ''; try { await walletApi.confirmMySettlement(settlementId.value); success.value = 'Pembayaran settlement dikonfirmasi dan saldo tenant dikurangi.'; settlementId.value = ''; await loadWallet(); } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Konfirmasi settlement gagal.'; } finally { busy.value = false; } };
onMounted(async () => { try { const response = await walletApi.myExhibitors(); exhibitors.value = response.data; selectedExhibitorId.value = exhibitors.value[0]?.exhibitor_id || ''; await loadWallet(); } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Daftar lapak belum dapat dimuat.'; } });
onBeforeUnmount(() => { (reader as unknown as { reset?: () => void } | null)?.reset?.(); if (retryTimer) clearInterval(retryTimer); });
useSeoMeta({ title: 'Scanner Tenant | Hari Santri 2026' });
</script>

<style scoped>
.scanner-page{min-height:72vh;background:#f5f5ef;color:#17352c;padding:3rem max(1rem,calc((100vw - 1000px)/2))}.scanner-inner{max-width:1000px;margin:auto}.eyebrow{color:#2d7258;font-size:.72rem;font-weight:800;letter-spacing:.12em}.intro{max-width:52rem;color:#596d61;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:2rem}.panel{background:#fff;border:1px solid #d9e0d8;padding:1.25rem}.date-filter{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin:1rem 0}.date-filter label{margin:0}.panel label{display:grid;gap:.4rem;margin-bottom:1rem;font-weight:800;color:#365444}input,select{font:inherit;padding:.7rem;border:1px solid #bdcdbf;border-radius:6px;font-weight:400}.reader{min-height:230px;border:1px dashed #9db1a1;margin:1rem 0}.button{border:1px solid #b8c9bd;padding:.7rem 1rem;font-weight:800;background:#fff;cursor:pointer}.secondary{color:#275d46}.primary{background:#d26c3e;color:#fff;border-color:#d26c3e}.full{width:100%}.balance strong{display:block;font:2.4rem Georgia,serif;margin:.7rem 0 1.5rem}.balance h2{font:1.35rem Georgia,serif}.error,.success{margin-top:1rem;padding:1rem;border-block:1px solid #d9e0d8}.error{color:#9a3022}.success{color:#21623b}table{width:100%;border-collapse:collapse}td{padding:.7rem .2rem;border-bottom:1px solid #edf1ed}@media(max-width:700px){.grid{grid-template-columns:1fr}}
</style>
